-- V27__insert_seoul_academy_data.sql
CREATE TABLE IF NOT EXISTS seoul_academy (
                                             id                BIGSERIAL PRIMARY KEY,
                                             academy_name      TEXT,
                                             district          VARCHAR(50),
    field             VARCHAR(100),
    subject_series    VARCHAR(100),
    subject_course    TEXT,
    address           TEXT,
    address_detail    TEXT,
    phone             VARCHAR(50),
    capacity          INTEGER,
    tuition_fee       TEXT,
    is_dormitory      BOOLEAN DEFAULT FALSE,
    registered_at     VARCHAR(20),
    created_at        TIMESTAMP DEFAULT NOW()
    );

CREATE INDEX IF NOT EXISTS idx_seoul_academy_district  ON seoul_academy(district);
CREATE INDEX IF NOT EXISTS idx_seoul_academy_field      ON seoul_academy(field);



















































